type Org={id:string;name:string};
type Task={id:string;organization_id:string;lead_id:string;title:string;due_at:string|null;completed:boolean;created_at:string};
type ActivityRow={id:string;lead_id:string;action:string;detail:string|null;created_at:string};
const sources=['Manual','Meta Ads','Instagram','WhatsApp','Formulario','Importación CSV','Referido','Otro'];
const intents=['Sin información','Interés general','Precio o cotización','Compra explícita','No interesado'];
const urgencies=['Desconocida','Inmediata','Este mes','Más adelante'];
const dt=(value:string|null|undefined)=>value?new Date(value).toLocaleString('es-PE',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const toLocalInput=(iso:string|null)=>{if(!iso)return '';const d=new Date(iso);if(Number.isNaN(d.getTime()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)};
const text=(value:unknown)=>String(value??'').trim();
const errText=(e:unknown)=>e instanceof Error?e.message:text(e);
// Reconoce campos explícitos. No infiere intención a partir de un simple «Hola».
const cleanHeader=(v:string)=>v.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
const cell=(row:Record<string,string>,...names:string[])=>names.map(n=>row[cleanHeader(n)]).find(x=>text(x).length>0)?.trim()??'';
const normalizedPhone=(v:string)=>v.replace(/[^0-9]/g,'');
const parsedStatus=(v:string)=>statuses.find(s=>cleanHeader(s)===cleanHeader(v))??'Por calificar';
const parsedIntent=(v:string)=>intents.find(s=>cleanHeader(s)===cleanHeader(v))??'Sin información';
const parsedUrgency=(v:string)=>urgencies.find(s=>cleanHeader(s)===cleanHeader(v))??'Desconocida';

const emptyLead={name:'',phone:'',email:'',source:'Manual',service:'',status:'Nuevo',intent:'Sin información',urgency:'Desconocida',notes:'',next_follow_up_at:'',value_estimate:''};
type LeadForm=typeof emptyLead;
function fromLead(l:Lead):LeadForm {return {name:l.name,phone:l.phone??'',email:l.email??'',source:l.source,service:l.service??'',status:l.status,intent:l.intent,urgency:l.urgency,notes:l.notes??'',next_follow_up_at:toLocalInput(l.next_follow_up_at),value_estimate:l.value_estimate?.toString()??''}}

